import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.map.js";
import { ref, computed, watch, onMounted, onBeforeUnmount } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getAuth, signOut, onAuthStateChanged } from "firebase/auth";
import { doc, getDoc, updateDoc, onSnapshot, Timestamp, collection, query, orderBy, limit, getDocs, addDoc } from "firebase/firestore";
import { db } from "../firebase";
export default {
  setup() {
    // State
    const username = ref("User");
    const role = ref("");
    const profileImage = ref("");
    const loading = ref(true);
    const lastLogin = ref(new Date());
    const loginCount = ref(0);
    const daysActive = ref(0);
    const profileCompletion = ref(0);
    const pendingRequests = ref(0);
    const showLogoutModal = ref(false);
    const sidebarOpen = ref(false);
    const defaultAvatar = "https://ui-avatars.com/api/?background=0F2942&color=fff";
    const recentActivities = ref([]);
    const stats = ref({
      submissions: 12,
      pending: 3,
      notifications: 5
    });
    const router = useRouter();
    const route = useRoute();
    const auth = getAuth();
    const currentRoute = computed(() => route.path);

    // Routes configuration
    const routes = [{
      path: '/',
      name: 'Home',
      icon: 'home'
    }, {
      path: '/register',
      name: 'Register',
      icon: 'user-plus'
    }, {
      path: '/login',
      name: 'Login',
      icon: 'log-in'
    }, {
      path: '/edit-profile',
      name: 'Edit Profile',
      icon: 'user-edit',
      meta: {
        requiresAuth: true,
        role: 'user'
      }
    }, {
      path: '/dashboard',
      name: 'Dashboard',
      icon: 'layout',
      meta: {
        requiresAuth: true
      }
    }, {
      path: '/profile-display',
      name: 'Profile',
      icon: 'user',
      meta: {
        requiresAuth: true,
        role: 'user'
      }
    }, {
      path: '/admin-dashboard',
      name: 'Admin Dashboard',
      icon: 'shield',
      meta: {
        requiresAuth: true,
        role: 'admin'
      }
    }, {
      path: '/reset-password',
      name: 'Reset Password',
      icon: 'key'
    }, {
      path: "/admin-management",
      name: "Admin Management",
      icon: 'users',
      meta: {
        requiresAuth: true,
        role: "admin"
      }
    }, {
      path: '/settings',
      name: 'Settings',
      icon: 'settings',
      meta: {
        requiresAuth: true
      }
    }, {
      path: '/purchase-requests',
      name: 'Request Purchase',
      icon: 'file-text',
      meta: {
        requiresAuth: true
      }
    }, {
      path: '/track-payments',
      name: 'Track Payments',
      icon: 'dollar-sign',
      meta: {
        requiresAuth: true
      }
    }, {
      path: '/approved-purchases',
      name: 'PR Lists',
      icon: 'check-circle',
      meta: {
        requiresAuth: true
      }
    }];

    // Group routes by section
    const navigationSections = computed(() => {
      return [{
        title: 'General',
        routes: routes.filter(r => r.path === '/' || r.path === '/dashboard' || r.path === '/profile-display')
      }, {
        title: 'Procurement',
        routes: routes.filter(r => r.path === '/purchase-requests' || r.path === '/track-payments' || r.path === '/approved-purchases')
      }, {
        title: 'User Management',
        routes: routes.filter(r => r.path === '/edit-profile' || r.path === '/reset-password')
      }, {
        title: 'Admin Controls',
        routes: routes.filter(r => r.path === '/admin-dashboard' || r.path === '/admin-management' || r.path === '/system-logs')
      }];
    });

    // Helper function to filter routes based on user role
    const getFilteredRoutes = routes => {
      return routes.filter(route => shouldShowRoute(route));
    };

    // Helper function to safely convert Firestore timestamp to Date
    const getDateFromTimestamp = timestamp => {
      if (timestamp instanceof Timestamp) {
        return timestamp.toDate();
      }
      if (timestamp && timestamp.seconds) {
        return new Timestamp(timestamp.seconds, timestamp.nanoseconds).toDate();
      }
      return new Date();
    };

    // Calculate profile completion
    const calculateProfileCompletion = userData => {
      const requiredFields = ['username', 'email', 'completeName', 'age', 'birthday', 'cellphone', 'gender', 'address'];
      const completedFields = requiredFields.filter(field => userData[field]);
      return Math.round(completedFields.length / requiredFields.length * 100);
    };

    // Update user data
    const updateUserData = async userDoc => {
      if (!userDoc) return;
      const userData = userDoc.data();
      username.value = userData.username || auth.currentUser?.displayName || "User";
      role.value = userData.role || "user";
      profileImage.value = userData.profileImageUrl;
      lastLogin.value = getDateFromTimestamp(userData.lastLogin);
      loginCount.value = userData.loginCount || 0;

      // Calculate days active
      const createdAt = getDateFromTimestamp(userData.createdAt);
      const diffTime = Math.abs(new Date() - createdAt);
      daysActive.value = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      // Calculate profile completion
      profileCompletion.value = calculateProfileCompletion(userData);

      // Fetch pending requests
      fetchPendingRequests(userDoc.id);

      // Fetch recent activities
      fetchRecentActivities(userDoc.id);
    };

    // Fetch pending requests
    const fetchPendingRequests = async userId => {
      try {
        const requestsRef = collection(db, "purchaseRequests");
        const q = query(requestsRef, orderBy("createdAt", "desc"));
        const querySnapshot = await getDocs(q);
        const requests = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        })).filter(req => req.userId === userId && req.status === "pending");
        pendingRequests.value = requests.length;
      } catch (error) {
        console.error("Error fetching pending requests:", error);
        pendingRequests.value = 0;
      }
    };

    // Fetch recent activities
    const fetchRecentActivities = async userId => {
      try {
        const activitiesRef = collection(db, "userActivities");
        const q = query(activitiesRef, orderBy("timestamp", "desc"), limit(5));
        const querySnapshot = await getDocs(q);
        recentActivities.value = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        })).filter(activity => activity.userId === userId);
      } catch (error) {
        console.error("Error fetching recent activities:", error);
        recentActivities.value = [];
      }
    };

    // Set up real-time listener for user data
    const setupUserListener = userId => {
      const userRef = doc(db, "users", userId);
      return onSnapshot(userRef, doc => {
        if (doc.exists()) {
          updateUserData(doc);
        }
      }, error => {
        console.error("Error listening to user data:", error);
      });
    };

    // Check if route should be shown based on user role
    const shouldShowRoute = route => {
      if (route.path === '/login' || route.path === '/register') {
        return false;
      }
      if (route.meta?.requiresAuth) {
        if (route.meta.role && route.meta.role !== role.value) {
          return false;
        }
      }
      return true;
    };

    // Get icon for each route
    const getIconForRoute = route => {
      const iconMap = {
        '/': 'home',
        '/dashboard': 'layout',
        '/profile-display': 'user',
        '/edit-profile': 'edit',
        '/reset-password': 'key',
        '/admin-dashboard': 'shield',
        '/admin-management': 'users',
        '/purchase-requests': 'file-text',
        '/track-payments': 'dollar-sign',
        '/approved-purchases': 'check-circle',
        '/system-logs': 'list',
        '/settings': 'settings'
      };
      return iconMap[route.path];
    };

    // Check if this is a new login session
    const isNewSession = () => {
      const lastSessionTime = sessionStorage.getItem('lastSessionTime');
      const currentTime = Date.now();
      if (!lastSessionTime) {
        sessionStorage.setItem('lastSessionTime', currentTime.toString());
        return true;
      }
      return false;
    };

    // Toggle sidebar
    const toggleSidebar = () => {
      sidebarOpen.value = !sidebarOpen.value;
      if (sidebarOpen.value) {
        document.body.style.overflow = 'hidden';
      } else {
        document.body.style.overflow = '';
      }
    };

    // Image error handler
    const handleImageError = e => {
      e.target.src = defaultAvatar;
    };

    // Robust date formatter for activity log
    const formatDate = timestamp => {
      let dateObj = null;
      if (!timestamp) return '—';
      // Firestore Timestamp object
      if (timestamp instanceof Timestamp) {
        dateObj = timestamp.toDate();
      } else if (timestamp.seconds) {
        dateObj = new Date(timestamp.seconds * 1000);
      } else if (typeof timestamp === 'string' || typeof timestamp === 'number') {
        dateObj = new Date(timestamp);
      } else if (timestamp instanceof Date) {
        dateObj = timestamp;
      }
      if (!dateObj || isNaN(dateObj.getTime())) return '—';
      // Format as e.g. Jun 29, 2025, 2:30 PM
      return dateObj.toLocaleString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        hour12: true
      });
    };
    const confirmLogout = () => {
      showLogoutModal.value = true;
    };
    const logout = async () => {
      try {
        sessionStorage.removeItem('lastSessionTime');
        await signOut(auth);
        router.push('/login');
      } catch (error) {
        console.error("Error logging out:", error);
      }
    };
    const navigateTo = route => {
      router.push(`/${route}`);
    };

    // Watch for route changes to close sidebar on mobile
    watch(currentRoute, () => {
      if (window.innerWidth < 768) {
        sidebarOpen.value = false;
        document.body.style.overflow = '';
      }
    });

    // Initialize component
    let unsubscribeUser = null;
    let unsubscribeAuth = null; // Declare unsubscribeAuth here

    onMounted(() => {
      unsubscribeAuth = onAuthStateChanged(auth, async user => {
        if (user) {
          try {
            if (unsubscribeUser) {
              unsubscribeUser();
            }
            unsubscribeUser = setupUserListener(user.uid);
            if (isNewSession()) {
              const userRef = doc(db, "users", user.uid);
              const userSnap = await getDoc(userRef);
              if (userSnap.exists()) {
                const userData = userSnap.data();
                await updateDoc(userRef, {
                  lastLogin: Timestamp.now(),
                  loginCount: (userData.loginCount || 0) + 1
                });

                // Log this activity
                try {
                  const activityRef = collection(db, "userActivities");
                  await addDoc(activityRef, {
                    userId: user.uid,
                    type: "login",
                    description: "User logged in",
                    timestamp: Timestamp.now()
                  });
                } catch (error) {
                  console.error("Error logging activity:", error);
                }
              }
            }

            // Fetch user role and log admin status
            const userRef = doc(db, "users", user.uid);
            const userDoc = await getDoc(userRef);
            if (userDoc.exists()) {
              const userData = userDoc.data();
              if (userData.role === "admin") {
                console.log("Admin logged in");
              } else {
                console.log("Non-admin user logged in");
              }
            }
          } catch (error) {
            console.error("Error setting up dashboard:", error);
          }
        } else {
          router.push('/login');
        }
        loading.value = false;
      });

      // Check saved sidebar state
      const savedSidebarState = localStorage.getItem('sidebarOpen');
      sidebarOpen.value = savedSidebarState === 'true';
    });

    // Cleanup on component unmount
    onBeforeUnmount(() => {
      if (unsubscribeAuth) {
        unsubscribeAuth();
      }
      if (unsubscribeUser) {
        unsubscribeUser();
      }
    });

    // Save sidebar state when changed
    watch(sidebarOpen, newValue => {
      localStorage.setItem('sidebarOpen', newValue);
    });
    return {
      username,
      role,
      profileImage,
      loading,
      lastLogin,
      loginCount,
      daysActive,
      profileCompletion,
      pendingRequests,
      showLogoutModal,
      sidebarOpen,
      defaultAvatar,
      recentActivities,
      currentRoute,
      navigationSections,
      getFilteredRoutes,
      getIconForRoute,
      toggleSidebar,
      handleImageError,
      formatDate,
      confirmLogout,
      logout,
      navigateTo,
      shouldShowRoute,
      stats
    };
  }
};
